package org.marketreview.nativeapp;
import org.json.*;import java.time.*;import java.util.*;import java.util.function.BooleanSupplier;
final class ChartAnnotationsInput {
 static String text(JSONObject o,String key,String fallback){Object v=o.opt(key);return v instanceof String?(String)v:fallback;}
 static double n(JSONObject o,String k){Object v=o.opt(k);return v instanceof Number?((Number)v).doubleValue():Double.NaN;}
 static double stamp(Object v){ChartAnnotationTime.Exact t=ChartAnnotationTime.parse(v);return t==null?Double.NaN:t.ms;}
 static Object number(double n){return Double.isFinite(n)?n:JSONObject.NULL;}
 static ChartAnnotations.Result calculate(JSONArray rows,JSONObject meta,int selected,BooleanSupplier cancelled)throws Exception{
  if(rows.length()>10000)throw new Exception("bar-limit-10000");ChartAnnotations.Context c=new ChartAnnotations.Context();c.source=text(meta,"source","");c.instrument=text(meta,"instrumentId","");c.period=text(meta,"period","");c.adjustment=text(meta,"adjustment","unknown");c.volumeUnit=text(meta,"volumeUnit","unknown");c.asOf=stamp(meta.has("asOf")?meta.opt("asOf"):meta.opt("checkedAt"));List<ChartAnnotations.Point> points=new ArrayList<>();
  if(meta.has("hostInstrumentId")&&!Objects.equals(meta.opt("hostInstrumentId"),meta.opt("instrumentId")))throw new Exception("host-source-identity-mismatch");if(meta.has("hostPeriod")&&!Objects.equals(meta.opt("hostPeriod"),meta.opt("period")))throw new Exception("host-source-period-mismatch");
  ChartAnnotationTime.Axis axis=new ChartAnnotationTime.Axis();Object sourceAsOf=meta.has("asOf")?meta.opt("asOf"):meta.opt("checkedAt");axis.add(sourceAsOf);for(int i=0;i<rows.length();i++){ChartAnnotations.active(cancelled);JSONObject row=rows.getJSONObject(i);for(String key:new String[]{"time","availableAt","closedAt"})axis.add(row.opt(key));}axis.seal();double displayAsOf=c.asOf;c.asOf=axis.rank(sourceAsOf);
  for(int i=0;i<rows.length();i++){ChartAnnotations.active(cancelled);JSONObject row=rows.getJSONObject(i);if((row.has("source")&&!Objects.equals(row.opt("source"),meta.opt("source")))||(row.has("instrumentId")&&!Objects.equals(row.opt("instrumentId"),meta.opt("instrumentId"))))throw new Exception("row-source-identity-mismatch");ChartAnnotations.Point p=new ChartAnnotations.Point(new Engine.Bar(n(row,"time"),n(row,"open"),n(row,"high"),n(row,"low"),n(row,"close"),n(row,"volume"),Boolean.TRUE.equals(row.opt("valid")),Boolean.TRUE.equals(row.opt("closed"))));p.date=text(row,"date",text(row,"label",""));if(p.date.isEmpty()&&Double.isFinite(p.bar.time)&&p.bar.time>=0&&p.bar.time<=253402214400000.0)p.date=java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSS'Z'").withZone(ZoneOffset.UTC).format(Instant.ofEpochMilli((long)p.bar.time));p.availableAt=stamp(row.opt("availableAt"));p.closedAt=stamp(row.opt("closedAt"));if((row.has("availableAt")&&!row.isNull("availableAt")&&!Double.isFinite(p.availableAt))||(row.has("closedAt")&&!row.isNull("closedAt")&&!Double.isFinite(p.closedAt)))throw new Exception("invalid-evidence-time");p.bar.time=row.opt("time") instanceof Number?axis.rank(row.opt("time")):Double.NaN;p.availableAt=axis.rank(row.opt("availableAt"));p.closedAt=axis.rank(row.opt("closedAt"));points.add(p);}ChartAnnotations.Result result=ChartAnnotations.calculate(points,c,selected,cancelled);result.context.asOf=displayAsOf;for(ChartAnnotations.Event e:result.events)if(Double.isFinite(e.dependenciesAvailableAt))e.dependenciesAvailableAt=axis.millis(e.dependenciesAvailableAt);return result;
 }
 static Object level(ChartAnnotations.Level l)throws Exception{if(!l.present)return JSONObject.NULL;JSONArray dates=new JSONArray(),touches=new JSONArray();for(ChartAnnotations.Touch t:l.touches){dates.put(t.date);touches.put(new JSONObject().put("index",t.index).put("confirmedIndex",t.confirmedIndex).put("date",t.date).put("price",t.price).put("rejected",t.rejected).put("volumeConfirmed",t.volumeConfirmed));}return new JSONObject().put("type",l.type).put("price",number(l.price)).put("distancePct",number(l.distancePct)).put("tolerance",number(l.tolerance)).put("strengthKey",l.strength).put("status",l.status).put("touchCount",l.touches.size()).put("rejectionCount",l.rejectionCount).put("volumeConfirmedTouches",l.volumeConfirmedTouches).put("touchDates",dates).put("touches",touches);}
 static JSONObject json(ChartAnnotations.Result r)throws Exception{JSONArray events=new JSONArray(),excluded=new JSONArray();for(int i=0;i<r.exclusions.size();i++)if(!r.exclusions.get(i).isEmpty())excluded.put(new JSONObject().put("index",i).put("reason",r.exclusions.get(i)));for(ChartAnnotations.Event e:r.events)events.put(new JSONObject().put("index",e.index).put("date",e.date).put("type",e.type).put("direction",e.direction).put("price",number(e.price)).put("triggerUsesFutureData",false).put("triggerUsesLaterBars",false).put("triggerObservedRealtime",false).put("triggerAvailability",e.triggerAvailability).put("dependenciesAvailableAt",number(e.dependenciesAvailableAt)).put("validationUsesFutureData",true).put("triggerEvidence",new JSONObject().put("close",number(e.close)).put("threshold",number(e.threshold)).put("priorWindowBars",20).put("volumeRatio",number(e.volumeRatio)).put("priceChangePct",number(e.priceChangePct))).put("validation",new JSONObject().put("status",e.validation.status).put("bars",e.validation.bars).put("forwardClosePct",number(e.validation.forwardClosePct)).put("maxPct",number(e.validation.maxPct)).put("minPct",number(e.validation.minPct)).put("asOf",number(r.context.asOf)).put("purpose","hindsight-only")));
  Object current=JSONObject.NULL;if(Double.isFinite(r.pivot))current=new JSONObject().put("pivot",r.pivot).put("resistance",new JSONObject().put("price",r.r1).put("sourceDate",r.sourceDate).put("distancePct",number(r.r1DistancePct))).put("support",new JSONObject().put("price",r.s1).put("sourceDate",r.sourceDate).put("distancePct",number(r.s1DistancePct)));
  return new JSONObject().put("schema","native.chart-annotations/v1").put("rulesVersion","webstock-chart-annotations/1.0.0").put("keyLevelRulesVersion","webstock-key-levels/1.0.0").put("boundaryVersion","native-closed-contiguous-asof/v1").put("status",r.status).put("reason",r.reason).put("source",r.context.source).put("instrumentId",r.context.instrument).put("period",r.context.period).put("asOf",number(r.context.asOf)).put("adjustment",r.context.adjustment).put("volumeUnit",r.context.volumeUnit).put("selectedIndex",r.selected).put("availabilityEvidence",r.snapshotOnly?"snapshot-only-reconstruction":"row-availability-declared").put("currentLevels",current).put("keyLevels",new JSONObject().put("lookbackBars",r.lookbackBars).put("tolerance",number(r.tolerance)).put("tolerancePct",number(r.tolerancePct)).put("support",level(r.support)).put("resistance",level(r.resistance))).put("events",events).put("excludedRows",excluded);
 }
 static String numeric(double n){return Double.isFinite(n)?String.format(Locale.ROOT,"%.4f",n):"—";}
 static String eventLabel(String t){switch(t){case "breakout-up":return "20根向上突破";case "breakout-down":return "20根向下跌破";case "gap-up":return "向上完整缺口";case "gap-down":return "向下完整缺口";default:return t.equals("volume-expansion-up")?"上涨放量":"下跌放量";}}
 static String availability(String s){return s.equals("declared-available-by-bar-close")?"来源声明当根闭合前已可用（不是实时触发日志）":s.equals("later-available-reconstruction")?"使用后到数据重建，不能称当时触发":"当根闭合时可用性未证实，仅快照重建";}
 static String summary(ChartAnnotations.Result r){StringBuilder text=new StringBuilder("本次状态：").append(r.status.equals("available")?"历史条件可计算":"不可用 · "+r.reason).append("\n所选原始位置：").append(r.selected+1).append("\n传统枢轴 P：").append(numeric(r.pivot)).append(" · R1压力：").append(numeric(r.r1)).append(" · S1支撑：").append(numeric(r.s1)).append("\n前一闭合周期：").append(r.sourceDate).append("\n");
  for(ChartAnnotations.Level l:new ChartAnnotations.Level[]{r.support,r.resistance}){if(!l.present){text.append("未形成一侧关键位；不补值。\n");continue;}text.append(l.type.equals("support")?"关键支撑":"关键压力").append("：").append(numeric(l.price)).append(" · 样本重复").append(l.strength.equals("strong")?"强":l.strength.equals("moderate")?"中":"弱").append("\n触碰 ").append(l.touches.size()).append(" 次 · 反向收盘 ").append(l.rejectionCount).append(" 次 · 量确认 ").append(l.volumeConfirmedTouches).append(" 次\n容差 ±").append(numeric(l.tolerance)).append(" · 相对所选收盘 ").append(numeric(l.distancePct)).append("%\n");for(ChartAnnotations.Touch t:l.touches)text.append("  ").append(t.date).append(" · 原始位置 ").append(t.index+1).append(" · 右侧确认至位置 ").append(t.confirmedIndex+1).append("\n");}
  text.append("\n历史事件与独立后验回看（").append(r.events.size()).append(" 项）\n");for(ChartAnnotations.Event e:r.events)text.append(e.date).append(" · ").append(eventLabel(e.type)).append("\n当根收盘 ").append(numeric(e.close)).append(" · 阈值 ").append(numeric(e.threshold)).append(" · 前20根量比 ").append(numeric(e.volumeRatio)).append(" · 收盘变化 ").append(numeric(e.priceChangePct)).append("%\n").append(availability(e.triggerAvailability)).append("\n后验回看：").append(e.validation.bars).append(" / 5 根 · ").append(e.validation.status.equals("pending")?"尚无后续完整根":e.validation.status.equals("partial")?"样本不全":"五根齐全").append("\n末根收盘相对变化 ").append(numeric(e.validation.forwardClosePct)).append("% · 区间最高变化 ").append(numeric(e.validation.maxPct)).append("% · 区间最低变化 ").append(numeric(e.validation.minPct)).append("%\n\n");return text.append("\n完整计算记录\n").toString();
 }
 static String explain(ChartAnnotations.Result r)throws Exception{String at=Double.isFinite(r.context.asOf)&&r.context.asOf>=0&&r.context.asOf<=253402214400000.0?Instant.ofEpochMilli((long)r.context.asOf).toString():"未知";return "来源："+r.context.source+" · 标的："+r.context.instrument+" · 周期："+r.context.period+"\n截至："+at+" · 复权："+r.context.adjustment+" · 成交量单位："+r.context.volumeUnit+"\n\n"+"关键位与历史事件 · 历史观察，不是预测或交易建议\n来源、截至时点、所选位置与完整结果见下方记录。\n前一完整周期：P=(高+低+收)/3，R1=2P−低，S1=2P−高。\n关键位：排除所选当根后的最多120根；左右各2根严格局部极值，仅在右侧2根已闭合后可确认。容差=max(所选收盘×0.5%, 历史最近14根TR算术均值×35%)。\n聚类按价位排序，逐次均值；选择距离收盘最近的可用支撑/压力。强=至少3次触碰且至少2次反向收盘；中=至少2次触碰；弱=1次。强弱只描述样本重复。\n反向收盘：低点触碰收在当根上半部，高点触碰收在下半部。量确认：此前最多20根有效量均值的1.2倍，至少5根；不改变强弱。\n事件优先级：严格突破前20根高低界 > 相邻完整区间缺口 > 成交量达前20根均量1.8倍且收盘变动绝对值至少1%。每根最多一类，保留最近16项。\n触发只使用该根及此前数据；validation 是截至快照时点后最多5根的后验回看，不参与触发。缺口中止回看，不补零、不跨缺口。\ntriggerUsesFutureData仅表示触发公式不读取后续根；triggerAvailability另行说明当根闭合时的数据可用性，晚到修订只能作重建。快照缺少逐根首次可用时间时，只能重建历史条件，不能声称当时实时触发；closed字段也是来源在快照时点的闭合声明。\n确认条件：核对同周期容差区内收盘、反向收盘、量能；持续越过容差区使原价位观察失效。复权、停牌、来源修订和周期会改变结果；不推断角色反转或缺口回补。\n\n"+summary(r)+json(r).toString(2);}
 static String explain(ChartAnnotations.Result r,JSONArray rows,JSONObject meta)throws Exception{return explain(r)+"\n来源原始时间（保留纳秒，不等同实时触发日志）：\n"+ChartAnnotationTime.evidence(rows,meta).toString(2);}

}
